# Traces: FR-3, ASR-1, ASR-2
"""Admin screen for adding, editing and deleting fraction questions."""

import tkinter as tk
from tkinter import messagebox, ttk

from ..question.models import QuestionType
from .screens import BaseScreen


class AdminScreen(BaseScreen):
    def __init__(self, app):
        super().__init__(app)
        self.service = app.admin_service
        self.selected_id = None

        tk.Label(self, text="Question admin", bg="#0b1026", fg="#7fd8ff", font=("Helvetica", 22, "bold")).pack(pady=10)

        form = tk.Frame(self, bg="#0b1026")
        form.pack(fill="x", padx=20, pady=6)
        self.prompt_var = tk.StringVar()
        self.answer_var = tk.StringVar()
        self.options_var = tk.StringVar()
        self.type_var = tk.StringVar(value=QuestionType.ADD.value)

        self._add_row(form, "Prompt", tk.Entry(form, textvariable=self.prompt_var, width=64), 0)
        self._add_row(form, "Options (comma separated)", tk.Entry(form, textvariable=self.options_var, width=64), 1)
        self._add_row(form, "Correct answer", tk.Entry(form, textvariable=self.answer_var, width=24), 2)
        ttk.Combobox(form, textvariable=self.type_var, values=[qt.value for qt in QuestionType], width=18, state="readonly").grid(row=2, column=2, padx=6, pady=4)

        buttons = tk.Frame(self, bg="#0b1026")
        buttons.pack(pady=6)
        tk.Button(buttons, text="Add question", command=self._add).pack(side="left", padx=4)
        tk.Button(buttons, text="Update selected", command=self._update).pack(side="left", padx=4)
        tk.Button(buttons, text="Delete selected", command=self._delete).pack(side="left", padx=4)
        tk.Button(buttons, text="Clear form", command=self._clear_form).pack(side="left", padx=4)

        list_frame = tk.Frame(self, bg="#0b1026")
        list_frame.pack(fill="both", expand=True, padx=20, pady=8)
        columns = ("id", "type", "prompt", "answer")
        self.tree = ttk.Treeview(list_frame, columns=columns, show="headings", height=10)
        for col, width in (("id", 50), ("type", 90), ("prompt", 420), ("answer", 110)):
            self.tree.heading(col, text=col.capitalize())
            self.tree.column(col, width=width, anchor="w")
        self.tree.pack(side="left", fill="both", expand=True)
        scroll = ttk.Scrollbar(list_frame, orient="vertical", command=self.tree.yview)
        scroll.pack(side="right", fill="y")
        self.tree.configure(yscrollcommand=scroll.set)
        self.tree.bind("<<TreeviewSelect>>", self._on_select)

        tk.Button(self, text="Back to menu", command=self.app.show_menu).pack(pady=8)
        self._refresh_list()

    def _add_row(self, parent, label, widget, row):
        tk.Label(parent, text=label, bg="#0b1026", fg="white").grid(row=row, column=0, sticky="w", pady=4)
        widget.grid(row=row, column=1, sticky="w", padx=6, pady=4)

    def _parse_options(self):
        options = [item.strip() for item in self.options_var.get().split(",") if item.strip()]
        if not options:
            raise ValueError("Provide at least one option, separated by commas.")
        return options

    def _read_form(self):
        prompt = self.prompt_var.get().strip()
        answer = self.answer_var.get().strip()
        options = self._parse_options()
        question_type = QuestionType(self.type_var.get())
        return prompt, options, answer, question_type

    def _clear_form(self):
        self.selected_id = None
        self.prompt_var.set("")
        self.options_var.set("")
        self.answer_var.set("")
        self.type_var.set(QuestionType.ADD.value)

    def _refresh_list(self):
        for item in self.tree.get_children():
            self.tree.delete(item)
        for question in self.service.list_questions():
            self.tree.insert("", "end", iid=str(question.id), values=(question.id, question.question_type.value, question.prompt, question.correct_answer))

    def _on_select(self, _event=None):
        selection = self.tree.selection()
        if not selection:
            return
        question_id = int(selection[0])
        question = self.service.repo.get(question_id)
        if question is None:
            return
        self.selected_id = question_id
        self.prompt_var.set(question.prompt)
        self.options_var.set(", ".join(question.options))
        self.answer_var.set(question.correct_answer)
        self.type_var.set(question.question_type.value)

    def _add(self):
        try:
            prompt, options, answer, question_type = self._read_form()
            self.service.add_question(prompt, options, answer, question_type)
            self._clear_form()
            self._refresh_list()
        except (ValueError, KeyError) as exc:
            messagebox.showerror("Invalid question", str(exc))

    def _update(self):
        if self.selected_id is None:
            messagebox.showinfo("No selection", "Select a question to update first.")
            return
        try:
            prompt, options, answer, question_type = self._read_form()
            self.service.update_question(self.selected_id, prompt, options, answer, question_type)
            self._refresh_list()
        except (ValueError, KeyError) as exc:
            messagebox.showerror("Invalid question", str(exc))

    def _delete(self):
        if self.selected_id is None:
            messagebox.showinfo("No selection", "Select a question to delete first.")
            return
        if messagebox.askyesno("Confirm delete", "Delete the selected question?"):
            self.service.delete_question(self.selected_id)
            self._clear_form()
            self._refresh_list()
